-- Versioned expense allocation and business calendar. Existing source ledgers stay immutable.
CREATE TABLE business_settings(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),timezone text NOT NULL DEFAULT 'Asia/Shanghai',version integer NOT NULL DEFAULT 1 CHECK(version>0),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expense_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),code text NOT NULL,external_reference text NOT NULL,category text NOT NULL,period_start date NOT NULL,period_end date NOT NULL CHECK(period_end>=period_start),amount_cents numeric(30,0) NOT NULL CHECK(amount_cents>0),basis text NOT NULL CHECK(basis IN ('time','output','auto','manual')),targets jsonb NOT NULL,source_snapshot jsonb NOT NULL,source_hash text NOT NULL,preview jsonb NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','reversed','cancelled')),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,code),UNIQUE(tenant_id,external_reference),FOREIGN KEY(tenant_id,created_by) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE expense_cost_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),expense_id uuid NOT NULL,work_order_id uuid NOT NULL,event_key text NOT NULL,amount_cents numeric(30,0) NOT NULL,allocation_snapshot jsonb NOT NULL,reversal_of uuid,created_by uuid NOT NULL,posted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,event_key),FOREIGN KEY(tenant_id,expense_id) REFERENCES expense_documents(tenant_id,id),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id),FOREIGN KEY(tenant_id,reversal_of) REFERENCES expense_cost_events(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES memberships(tenant_id,user_id));
CREATE INDEX expense_cost_wo ON expense_cost_events(tenant_id,work_order_id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['business_settings','expense_documents','expense_cost_events'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY %I ON %I TO gd_tenant USING (tenant_id::text=nullif(current_setting(''app.tenant_id'',true),'''')) WITH CHECK(tenant_id::text=nullif(current_setting(''app.tenant_id'',true),''''))',t||'_tenant',t);
END LOOP;END $$;
GRANT SELECT,INSERT,UPDATE ON business_settings,expense_documents TO gd_tenant;
GRANT SELECT,INSERT ON expense_cost_events TO gd_tenant;
CREATE FUNCTION prevent_expense_cost_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'expense cost ledger is append only'; END $$;
CREATE TRIGGER expense_cost_events_append_only BEFORE UPDATE OR DELETE ON expense_cost_events FOR EACH ROW EXECUTE FUNCTION prevent_expense_cost_mutation();
ALTER TABLE document_counters DROP CONSTRAINT document_counters_doc_type_check;
ALTER TABLE document_counters ADD CONSTRAINT document_counters_doc_type_check CHECK(doc_type IN ('SO','WO','RP','MI','FG','SH','AD','QC','PO','PR','IQC','MRP','PAYROLL','RC','PC','SP','RW','EX'));
